import sys

data = sys.stdin.read().split()
n = int(data[0])
words = data[1:1 + n]
where = {}
for i, w in enumerate(words, 1):
    where.setdefault(w, []).append(i)
total = 0
longest = 0
for positions in where.values():
    for a, b in zip(positions, positions[1:]):
        gap = b - a
        total += gap
        if gap > longest:
            longest = gap
print(total, longest)
